if(path==='/v1/parent/family'&&method==='GET'){const auth=authenticate(request);if(!['parent','admin'].includes(auth.role))return fail(json,response,'forbidden',requestId,403);const where=auth.role==='parent'?'WHERE l.parent_id=$1':'';const params=auth.role==='parent'?[auth.sub]:[];const {rows}=await pool.query('SELECT l.parent_id,l.student_id,l.status,l.created_at,p.full_name,u.email,i.document_number,e.section_id,e.grade_id,e.course_id,s.name section,g.name grade,c.name course FROM quickbite.family_links l JOIN quickbite.users u ON u.id=l.student_id JOIN quickbite.profiles p ON p.user_id=u.id LEFT JOIN quickbite.user_identity i ON i.user_id=u.id LEFT JOIN quickbite.student_enrollments e ON e.user_id=u.id LEFT JOIN quickbite.academic_sections s ON s.id=e.section_id LEFT JOIN quickbite.academic_grades g ON g.id=e.grade_id LEFT JOIN quickbite.academic_courses c ON c.id=e.course_id '+where+' ORDER BY p.full_name',params);return ok(response,json,200,{items:rows},requestId)}
