if(path==='/v1/parent/food-controls'&&(method==='GET'||method==='PUT')){const auth=authenticate(request);const body=method==='PUT'?await readJson(request):null;const studentId=String(body?.studentId||url.searchParams.get('studentId')||'');if(!studentId)return fail(json,response,'student_required',requestId);if(auth.role!=='admin'&&!(await isParentOf(pool,auth.sub,studentId)))return fail(json,response,'not_authorized',requestId,403);if(method==='GET'){const {rows}=await pool.query('SELECT p.id,p.name,p.description,p.price,p.category_id,p.image_url,p.available,i.quantity AS stock,c.name AS category_name,b.id AS block_id,b.reason AS block_reason FROM quickbite.products p LEFT JOIN quickbite.inventory i ON i.product_id=p.id LEFT JOIN quickbite.categories c ON c.id=p.category_id LEFT JOIN quickbite.parent_food_blocks b ON b.product_id=p.id AND b.parent_id=$2 AND b.student_id=$1 WHERE p.active ORDER BY c.name,p.name',[studentId,auth.sub]);return ok(response,json,200,{items:rows.map(r=>({...r,blocked:Boolean(r.block_id),reason:r.block_reason??null}))},requestId)}if(body.blocked)await pool.query('INSERT INTO quickbite.parent_food_blocks(parent_id,student_id,product_id,reason) VALUES($1,$2,$3,$4) ON CONFLICT(parent_id,student_id,product_id) DO UPDATE SET reason=EXCLUDED.reason',[auth.sub,studentId,body.productId,body.reason||null]);else await pool.query('DELETE FROM quickbite.parent_food_blocks WHERE parent_id=$1 AND student_id=$2 AND product_id=$3',[auth.sub,studentId,body.productId]);return ok(response,json,200,{blocked:Boolean(body.blocked)},requestId)}
if(path==='/v1/parent/wellbeing'&&(method==='GET'||method==='PUT')){const auth=authenticate(request);const body=method==='PUT'?await readJson(request):null;const studentId=String(body?.studentId||url.searchParams.get('studentId')||'');if(!studentId||auth.role!=='admin'&&!(await isParentOf(pool,auth.sub,studentId)))return fail(json,response,'not_authorized',requestId,403);if(method==='GET'){const limits=(await pool.query('SELECT * FROM quickbite.student_spending_limits WHERE student_id=$1',[studentId])).rows[0]??{};const spending=(await pool.query("SELECT COALESCE(SUM(total) FILTER(WHERE created_at>=date_trunc('day',now())),0) today,COALESCE(SUM(total) FILTER(WHERE created_at>=date_trunc('week',now())),0) week,COALESCE(SUM(total) FILTER(WHERE created_at>=date_trunc('month',now())),0) month FROM quickbite.orders WHERE user_id=$1 OR beneficiary_user_id=$1",[studentId])).rows[0];const nutrition=(await pool.query('SELECT product_id,calories,protein_g,carbohydrates_g,fat_g,fiber_g,ingredients,allergens,vegetarian,healthy_choice FROM quickbite.product_nutrition')).rows;return ok(response,json,200,{limits,spending:{today:num(spending.today),week:num(spending.week),month:num(spending.month)},nutrition},requestId)}const vals=['dailyLimit','weeklyLimit','monthlyLimit'];for(const k of vals)if(body[k]!=null&&num(body[k])<0)return fail(json,response,'invalid_spending_limit',requestId);const {rows}=await pool.query('INSERT INTO quickbite.student_spending_limits(student_id,daily_limit,weekly_limit,monthly_limit) VALUES($1,$2,$3,$4) ON CONFLICT(student_id) DO UPDATE SET daily_limit=EXCLUDED.daily_limit,weekly_limit=EXCLUDED.weekly_limit,monthly_limit=EXCLUDED.monthly_limit,updated_at=now() RETURNING *',[studentId,body.dailyLimit??null,body.weeklyLimit??null,body.monthlyLimit??null]);return ok(response,json,200,{limits:rows[0]},requestId)}
